INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('kr-passport', '표정은 무표정, 입은 다문 상태. 안경 착용 가능(렌즈 반사·프레임 주의). 머리카락이 이마를 가리면 안 됨. 귀 노출 권장.', 'Neutral expression, mouth closed. Glasses allowed (watch for lens glare and frame obstruction). Hair must not cover forehead.', '表情は無表情、口は閉じた状態。メガネ着用可能（レンズ反射・フレーム注意）。前髪が額を隠してはならない。', '["배경에 그림자","머리 기울어짐","이마를 가린 머리카락","조명 불균일","사이즈 불일치"]', '["Shadow on background","Head tilt","Hair covering forehead","Uneven lighting","Wrong size"]', '["背景に影","頭の傾き","額を隠す髪","照明の不均一","サイズ不一致"]', '[{"q":"여권사진 배경은 흰색만 가능한가요?","a":"네, 대한민국 여권사진은 균일한 흰색 배경만 허용됩니다. 그림자나 무늬가 있으면 반려됩니다."},{"q":"안경 쓰고 여권사진 찍어도 되나요?","a":"네, 안경 착용이 가능합니다. 다만 렌즈 반사가 없어야 하고 프레임이 눈을 가리면 안 됩니다."},{"q":"여권사진 셀프로 찍을 수 있나요?","a":"네, 규격만 맞으면 셀프 촬영도 가능합니다. MONKOS AI를 사용하면 배경 제거와 규격 크롭을 자동으로 처리합니다."},{"q":"여권사진 유효기간이 있나요?","a":"촬영 후 6개월 이내의 사진만 사용할 수 있습니다."},{"q":"여권사진 집에서 찍어도 되나요?","a":"네, 3.5×4.5cm 규격과 흰색 배경 등 조건만 충족하면 집에서 촬영해도 됩니다. MONKOS AI를 쓰면 배경 자동 제거와 규격 크롭까지 처리됩니다."},{"q":"여권사진 메이크업 주의사항이 있나요?","a":"자연스러운 메이크업은 허용됩니다. 다만 얼굴 윤곽을 크게 바꾸는 과한 컨투어링이나 컬러 렌즈는 반려 사유가 될 수 있습니다."}]', '[{"q":"Does the passport photo background have to be white?","a":"Yes, a solid white background is required. Shadows or patterns will cause rejection."},{"q":"Can I wear glasses in a passport photo?","a":"For Korea, glasses are allowed but watch for lens glare and frame obstruction. For Japan, removing glasses is strongly recommended."},{"q":"Can I take a passport photo by myself?","a":"Yes, as long as it meets the specifications. MONKOS AI automatically removes the background and crops to the correct size."}]', '[{"q":"パスポート写真の背景は白のみですか？","a":"はい、均一な白背景のみ許可されています。影や模様があると却下されます。"},{"q":"メガネをかけてパスポート写真を撮れますか？","a":"撮影可能ですが、レンズの反射がないことが条件です。"},{"q":"セルフでパスポート写真を撮れますか？","a":"はい、規格を満たせばセルフ撮影も可能です。MONKOS AIで背景除去と規格クロップを自動処理できます。"}]', '여권사진 규격 2026 — 사이즈·배경·복장 총정리 | MONKOS', 'Korea Passport Photo Size 2026 — Requirements & Free AI Tool | MONKOS', '韓国パスポート写真 規格 2026 — サイズ・背景・服装 総まとめ | MONKOS', '한국 여권사진 3.5×4.5cm, 흰색 배경, 6개월 이내. 반려 사유 5가지와 셀프 촬영 팁까지. 무료 AI 증명사진 도구로 바로 만들기.', 'Korea passport photo 3.5×4.5cm, white background, within 6 months. Top 5 rejection reasons and selfie tips. Make yours free with AI.', '韓国パスポート写真 3.5×4.5cm、白背景、6ヶ月以内。却下理由5つとセルフ撮影のコツ。無料AIツールで今すぐ作成。', 'idphoto-kr');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('kr-resume', '이력서, 학생증, 자격증 등 사기관 제출용. 사이즈(3×4cm)만 통일되어 있으며 픽셀·배경·파일 등 세부 규격은 공식 규정 없음. 제출처 요구사항을 확인할 것.', 'For resumes, student IDs, certificates. Only the size (3×4cm) is standardized — no official regulation for pixels, background, or file specs. Check requirements of the submitting institution.', '履歴書、学生証、資格証など各機関提出用。サイズ（3×4cm）のみ統一で、公式な細則は定められていない。提出先の要件を確認すること。', '["사이즈 불일치 (여권 규격과 혼동)","배경 불균일","머리 잘림","표정 부적합","해상도 부족"]', '["Wrong size (confused with passport)","Uneven background","Head cropped","Inappropriate expression","Low resolution"]', '["サイズ不一致","背景不均一","頭切れ","表情不適合","解像度不足"]', '[{"q":"반명함과 여권사진 차이가 뭔가요?","a":"사이즈가 다릅니다. 여권사진은 3.5×4.5cm, 반명함은 3×4cm입니다. 반명함은 공식 규정이 없어 제출처마다 요구사항이 다를 수 있습니다."},{"q":"이력서 사진도 정장을 입어야 하나요?","a":"필수는 아니지만 권장됩니다. 비즈니스 캐주얼 이상이 일반적입니다."},{"q":"반명함 사진을 온라인으로 제출할 수 있나요?","a":"네, MONKOS에서 디지털 파일로 다운로드하여 온라인 제출이 가능합니다."}]', '[{"q":"What''s the difference between resume and passport photo?","a":"Only the size differs. Passport is 3.5×4.5cm, resume is 3×4cm."},{"q":"Do I need to wear a suit for a resume photo?","a":"Not required, but business casual or above is recommended."}]', '[{"q":"半名刺とパスポート写真の違いは？","a":"サイズのみ異なります。パスポートは3.5×4.5cm、半名刺（履歴書）は3×4cmです。"},{"q":"履歴書写真はスーツ必須ですか？","a":"必須ではありませんが、ビジネスカジュアル以上が推奨されます。"}]', NULL, NULL, NULL, NULL, NULL, NULL, 'idphoto-kr');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('jp-passport', '일본 여권사진은 흰색 배경 강력 권장(2025년 신여권 흑백 레이저 인쇄). 안경 제거 강력 권장(외무성). 머리 높이 34±2mm. 온라인 제출 시 600×730px, 600KB 이하.', 'White background strongly recommended (2025 new passport uses B&W laser printing). Removing glasses strongly recommended (MOFA). Head height 34±2mm. Online: 600×730px, max 600KB.', '白背景を強く推奨（2025年新パスポートはレーザー白黒印刷）。メガネは外すことを推奨（外務省）。頭の高さ34±2mm。オンライン提出時600×730px、600KB以下。', '["배경색 부적합","얼굴 비율 초과/미달","안경 반사","그림자","사이즈 불일치"]', '["Wrong background color","Face ratio out of range","Glasses glare","Shadow","Wrong size"]', '["背景色不適合","顔比率超過/不足","メガネ反射","影","サイズ不一致"]', '[{"q":"일본 여권사진에 안경을 써도 되나요?","a":"외무성은 안경 제거를 강력 권장합니다. 의료상 필요한 경우만 허용되며, 렌즈 반사·프레임이 눈을 가리면 안 됩니다."},{"q":"일본 여권사진 배경은 흰색만 가능한가요?","a":"흰색 또는 연한 회색(라이트그레이)이 허용됩니다."}]', '[{"q":"Can I wear glasses in a Japanese passport photo?","a":"Yes, as long as there is no glare on the lenses."},{"q":"What background color for Japanese passport photo?","a":"White or light gray is accepted."}]', '[{"q":"パスポート写真にメガネをかけてもいいですか？","a":"外務省はメガネを外すことを強く推奨しています。医療上の理由がある場合のみ着用可能ですが、レンズ反射やフレームが目を隠すと却下されます。"},{"q":"パスポート写真の背景は白のみですか？","a":"白または薄いグレーが許可されています。"},{"q":"パスポート写真をスマホで撮れますか？","a":"はい、規格を満たせばスマホ撮影も可能です。MONKOS AIで自動処理できます。"}]', NULL, NULL, NULL, NULL, NULL, NULL, 'idphoto-jp');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('jp-resume', '일본 취직활동(就活)용. 3개월 이내 촬영 권장. 정장 착용이 사실상 필수.', 'For Japanese job hunting (shūkatsu). Photos within 3 months recommended. Business suit practically required.', '就職活動用。3ヶ月以内の撮影を推奨。スーツ着用が事実上必須。', '["사이즈 불일치","정장 미착용","표정 부적합","촬영일 초과","배경 불균일"]', '["Wrong size","No business suit","Inappropriate expression","Photo too old","Uneven background"]', '["サイズ不一致","スーツ未着用","表情不適合","撮影日超過","背景不均一"]', '[{"q":"일본 이력서 사진은 반드시 정장인가요?","a":"법적 필수는 아니지만, 취직활동에서는 사실상 필수입니다. 검은색 또는 네이비 정장이 표준입니다."}]', '[{"q":"Is a suit required for Japanese resume photos?","a":"Not legally, but practically required for job hunting. Black or navy suit is standard."}]', '[{"q":"履歴書写真は必ずスーツですか？","a":"法的義務ではありませんが、就活では事実上必須です。黒またはネイビーのスーツが標準です。"},{"q":"履歴書写真の有効期限は？","a":"一般的に3ヶ月以内が推奨されます。企業によっては6ヶ月以内でも可。"},{"q":"コンビニでプリントできますか？","a":"はい、ローソン・セブンイレブン・ファミマのマルチコピー機で印刷可能です。MONKOS AIで作成→ダウンロード→コンビニプリント。"}]', NULL, NULL, NULL, NULL, NULL, NULL, 'idphoto-jp');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('us-passport', '미국 여권·비자·그린카드 공통 규격. 정사각형(2×2인치). 안경 착용 불가(2016년 11월부터). 600×600~1200×1200px. 비자(DS-160)와 여권 온라인 갱신의 파일 제한이 다름.', 'Standard for US passport, visa, and green card. Square format (2×2 inch). Glasses not allowed since Nov 2016. 600×600 to 1200×1200px. File limits differ between visa (DS-160: max 240KB) and passport renewal (54KB–10MB).', '米国パスポート・ビザ・グリーンカード共通規格。正方形（2×2インチ）。メガネ不可（2016年11月から）。600×600〜1200×1200px。', '["사이즈 불일치 (정사각형 아님)","안경 착용","그림자","배경 불균일","얼굴 비율 부적합"]', '["Wrong size (not square)","Wearing glasses","Shadow","Uneven background","Face proportion out of range"]', '["サイズ不一致（正方形でない）","メガネ着用","影","背景不均一","顔比率不適合"]', '[{"q":"미국 여권사진은 왜 정사각형인가요?","a":"미국 국무부 규정입니다. 2×2인치(51×51mm) 정사각형이 표준이며, 다른 국가와 규격이 다릅니다."}]', '[{"q":"Why is the US passport photo square?","a":"It''s a US State Department requirement. 2×2 inches (51×51mm) is the standard."},{"q":"Can I wear glasses in a US passport photo?","a":"No, glasses have not been allowed in US passport photos since November 2016."},{"q":"Can I smile in a US passport photo?","a":"A natural, neutral expression is required. No wide smiles."}]', '[{"q":"アメリカのパスポート写真はなぜ正方形？","a":"米国国務省の規定です。2×2インチ（51×51mm）の正方形が標準です。"}]', NULL, NULL, NULL, NULL, NULL, NULL, 'idphoto-kr');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('kr-drivers-license', '여권사진과 동일 사이즈(3.5×4.5cm). 도로교통공단 온라인 접수 시 디지털 파일 제출 가능. 온라인 제출 픽셀은 350×450px, 파일크기 250KB 이하.', 'Same size as passport (3.5×4.5cm). For online submission: 350×450px, max 250KB.', 'パスポート写真と同サイズ（3.5×4.5cm）。オンライン提出時は350×450px、250KB以下。', '["사이즈 불일치","배경 불균일","안경 반사","모자·선글라스 착용","사진 오래됨"]', '["Wrong size","Uneven background","Glasses glare","Hat or sunglasses","Photo too old"]', '["サイズ不一致","背景不均一","メガネ反射","帽子・サングラス着用","写真が古い"]', '[{"q":"운전면허증 사진 규격이 여권사진과 같나요?","a":"네, 동일한 3.5×4.5cm 규격입니다. 여권사진으로 운전면허 갱신도 가능합니다."},{"q":"운전면허증 사진을 온라인으로 제출할 수 있나요?","a":"도로교통공단 홈페이지에서 온라인 접수 시 디지털 파일을 업로드할 수 있습니다."}]', '[{"q":"Is the driver''s license photo the same as passport?","a":"Yes, same 3.5×4.5cm size in Korea."}]', '[{"q":"運転免許証の写真規格はパスポートと同じ？","a":"はい、同じ3.5×4.5cm規格です。"}]', '운전면허 사진 규격 2026 — 사이즈·배경·온라인 제출 총정리 | MONKOS', 'Korea Driver''s License Photo Size 2026 — Requirements Guide | MONKOS', '韓国運転免許証 写真規格 2026 — サイズ・背景 総まとめ | MONKOS', '운전면허 증명사진 3.5×4.5cm, 온라인 제출 350×450px 250KB 이하. 여권사진과 같은 규격이라 하나로 해결. 무료 AI 도구로 바로 만들기.', 'Korea driver''s license photo 3.5×4.5cm, online submission 350×450px max 250KB. Same as passport size. Make it free with AI.', '韓国運転免許証写真 3.5×4.5cm。オンライン提出は350×450px、250KB以下。無料AIツールで作成。', 'idphoto-kr');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('jp-national-id', '일본 마이넘버(개인번호) 카드 신청용. 여권사진과 동일 규격. 온라인 신청 시 스마트폰 촬영 가능.', 'For My Number Card application. Same specs as passport. Smartphone photos accepted for online applications.', 'マイナンバーカード申請用。パスポートと同一規格。オンライン申請時スマホ撮影可能。', '["사이즈 불일치","배경 불균일","그림자","파일 용량 초과","얼굴 비율 부적합"]', '["Wrong size","Uneven background","Shadow","File too large","Face proportion out of range"]', '["サイズ不一致","背景不均一","影","ファイル容量超過","顔比率不適合"]', '[{"q":"마이넘버카드 사진을 스마트폰으로 찍어도 되나요?","a":"네, 온라인 신청 시 스마트폰 촬영이 허용됩니다."}]', '[{"q":"Can I take a My Number Card photo with my phone?","a":"Yes, smartphone photos are accepted for online applications."}]', '[{"q":"マイナンバーカードの写真はスマホで撮れますか？","a":"はい、オンライン申請ではスマホ撮影が認められています。MONKOS AIで規格に合わせて自動処理できます。"},{"q":"マイナンバーカードの写真規格はパスポートと同じ？","a":"はい、3.5×4.5cm、白背景で同一規格です。"}]', NULL, NULL, NULL, NULL, NULL, NULL, 'idphoto-jp');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('kr-national-id', '주민등록증 발급/재발급용. 여권사진과 동일 규격(35×45mm). 무표정, 안경 착용 가능.', 'For resident ID card issuance. Same specs as passport (35×45mm).', '住民登録証発行用。パスポートと同一規格（35×45mm）。', '["배경 불균일","사이즈 불일치","안경 반사","표정 부적합"]', '["Uneven background","Wrong size"]', '["背景不均一","サイズ不一致"]', '[{"q":"주민등록증 사진도 여권사진과 같나요?","a":"네, 동일한 35×45mm 규격입니다."}]', '[]', '[]', '주민등록증 사진 규격 2026 — 사이즈·배경·촬영 팁 총정리 | MONKOS', 'Korea Resident ID Photo Size 2026 — Requirements Guide | MONKOS', '韓国住民登録証 写真規格 2026 — サイズ・背景 総まとめ | MONKOS', '주민등록증 증명사진 35×45mm 규격 안내. 여권사진과 동일 사이즈라 한 번에 해결. 무료 AI 도구로 집에서 바로 만들기.', 'Korea resident ID photo 35×45mm. Same specs as passport. Make it free with MONKOS AI.', '韓国住民登録証写真 35×45mm。パスポートと同一規格。無料AIツールで作成可能。', 'idphoto-kr');
INSERT INTO seo_content (document_id, details_ko, details_en, details_ja, rejection_reasons_ko, rejection_reasons_en, rejection_reasons_ja, faqs_ko, faqs_en, faqs_ja, seo_title_ko, seo_title_en, seo_title_ja, seo_description_ko, seo_description_en, seo_description_ja, cta_service) VALUES ('jp-residence-card', '외국인 재류자격 카드용. 30×40mm 흰색 배경.', 'For residence card application. 30×40mm white background.', '在留カード申請用。30×40mm白背景。', '["배경 불균일","사이즈 불일치"]', '["Uneven background","Wrong size"]', '["背景不均一","サイズ不一致"]', '[]', '[]', '[{"q":"在留カードの写真はパスポートと同じですか？","a":"サイズが異なります。在留カードは30×40mm、パスポートは35×45mmです。"}]', NULL, NULL, NULL, NULL, NULL, NULL, 'idphoto-jp');
